 '<section class="panel"><div class="section-title"><h2>'+t('أرقام MPC والدرجات الفعلية','MPC IDs and calculated longitudes')+'</h2><label class="heat-label">'+t('المجال','Domain')+' <select id="asteroid-category"><option value="all">'+t('الكل','All')+'</option>'+categories.map(c=>'<option value="'+c+'" '+(asteroidCategory===c?'selected':'')+'>'+cat(c)+'</option>').join('')+'</select></label></div><div class="asteroids-grid">'+filtered.map(a=>{const point=map.get(a.name);return '<div class="asteroid-item"><b>'+esc(a.name)+'</b><span>MPC '+a.number+' · Swiss '+a.swissBodyId+'</span>'+(point?'<strong>'+signName(point.longitude)+' · '+(point.longitude%30).toFixed(4)+'° '+(point.speed<0?'℞':'')+'</strong>':'<small>'+t('لا توجد مواضع محسوبة للوقت المحدد','No valid position at selected instant')+'</small>')+'<small>'+a.areas.map(cat).join(' · ')+'</small><code>'+esc(asteroidSourcePath(a.number))+'</code></div>'}).join('')+'</div></section>'+
 (additional.length?'<section class="panel"><h2>'+t('زوايا الكويكبات الجديدة مع الولادة','Computed additional asteroid-to-natal contacts')+'</h2><p>'+t('هاي الزوايا محسوبة من المواقع الفعلية للملفات المحمّلة، وتبقى مفصولة عن المؤشرات الـ8 الأساسية حتى ما نغيّر نموذج الحساب بدون تحقق.','These contacts use loaded asteroid positions; they are kept separate from the eight core source indices until the extended scoring model is validated.')+'</p><div class="eclipse-contacts">'+additional.map(e=>'<span><b>'+esc(e.transit.id)+' → '+planet(e.natal.id)+'</b>'+aspect(e.angle)+' · orb '+e.orb.toFixed(3)+'° · '+(e.applying?t('مقترب','Applying'):t('مبتعد','Separating'))+'</span>').join('')+'</div></section>':'');
